per_case_results.actual_sql:
SELECT "team_fifa_api_id"
FROM "Team_Attributes"
WHERE "build_up_play_speed" > 50 AND "build_up_play_speed" < 60;

SELECT "player_name"
FROM "players"
WHERE "height" = (
    SELECT MAX("height") FROM "players"
)
OR "height" = (
    SELECT MIN("height") FROM "players"
)
ORDER BY "finishing_rate" DESC
LIMIT 1;

SELECT "name" 
FROM "players" 
WHERE "volley" > 70 AND "dribbling" > 70;

SELECT AVG("overall_rating") 
FROM "reviews" 
WHERE "reviewer_name" = 'Pietro Marino';

SELECT 
    (COUNT(CASE WHEN "height" < 180 AND "overall" > 70 THEN 1 END) * 100.0 / COUNT(*)) AS percentage
FROM "players";
